-- The four categories of the shop
SELECT * FROM categories ORDER BY id;

-- Every product: name, price and stock, cheapest first
SELECT name, price, stock
FROM products
ORDER BY price;

-- Products under 2 euros
SELECT name, price FROM products WHERE price < 2 ORDER BY price;

-- Out of stock
SELECT name, stock FROM products WHERE stock = 0 ORDER BY name;

-- A boolean column works as a condition on its own
SELECT name, active FROM products WHERE NOT active;

-- Orders that are not shipped yet
SELECT id, customer_id, ordered, status, total
FROM orders
WHERE status <> 'shipped'
ORDER BY ordered;

-- NULL is not equal to anything, not even NULL
SELECT NULL = NULL AS equal, NULL IS NULL AS is_null, 1 + NULL AS plus;

-- The customer without email: = NULL finds nothing, IS NULL does
SELECT name FROM customers WHERE email = NULL;
SELECT name, city FROM customers WHERE email IS NULL;

-- coalesce gives a fallback, nullif turns a value into NULL
SELECT r.id,
       r.rating,
       coalesce(r.comment, '(no comment)') AS comment,
       nullif(r.rating, 5) AS not_five
FROM reviews r
ORDER BY r.id;

-- Several sort keys: category first, then the most expensive
SELECT category_id, name, price
FROM products
ORDER BY category_id, price DESC
LIMIT 6;

-- The second page of three: OFFSET skips rows
SELECT name, price FROM products ORDER BY price LIMIT 3 OFFSET 3;

-- DESC puts NULL first; NULLS LAST sends it to the end
SELECT name, email FROM customers ORDER BY email DESC LIMIT 2;
SELECT name, email FROM customers ORDER BY email DESC NULLS LAST LIMIT 2;

-- FETCH FIRST ... WITH TIES keeps the rows that tie with the last one
SELECT name, stock
FROM products
ORDER BY stock
FETCH FIRST 1 ROWS WITH TIES;

-- A table of suppliers with identity, constraints and defaults
CREATE TABLE suppliers (
  id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name text NOT NULL UNIQUE,
  country text NOT NULL DEFAULT 'Spain',
  rating smallint CHECK (rating BETWEEN 1 AND 5),
  since date NOT NULL DEFAULT '2024-01-01',
  category_id integer REFERENCES categories (id)
);

INSERT INTO suppliers (name, rating, category_id)
VALUES ('Harinas del Sur', 5, 1), ('Lácteos Norte', 4, 3);

INSERT INTO suppliers (name, country, rating, since, category_id)
VALUES ('Café Andino', 'Colombia', 4, '2024-03-10', 2);

ALTER TABLE suppliers ADD COLUMN email text;

SELECT s.id, s.name, s.country, s.rating, s.since, c.name AS category
FROM suppliers s
JOIN categories c ON c.id = s.category_id
ORDER BY s.id;

