-- A view is a saved query: it is always up to date
CREATE VIEW customer_sales AS
SELECT c.id, c.name, c.city, count(o.id) AS orders, coalesce(sum(o.total), 0) AS spent
FROM customers c
LEFT JOIN orders o ON o.customer_id = c.id AND o.status <> 'cancelled'
GROUP BY c.id;

-- A materialized view stores the result: fast, but a snapshot
CREATE MATERIALIZED VIEW city_sales AS
SELECT city, sum(orders) AS orders, sum(spent) AS spent
FROM customer_sales
GROUP BY city;

-- A new order for Carlos (Bilbao)
INSERT INTO orders (customer_id, ordered, status, total)
VALUES (8, '2024-06-10', 'paid', 12.00);

-- The view sees it; the materialized view does not, until REFRESH
SELECT name, orders, spent FROM customer_sales WHERE id = 8;
SELECT city, orders, spent FROM city_sales WHERE city = 'Bilbao';

REFRESH MATERIALIZED VIEW city_sales;

SELECT city, orders, spent FROM city_sales ORDER BY spent DESC;

-- A bigger table: 20,000 order lines made with generate_series
CREATE TABLE big_items AS
SELECT n AS id, n % 500 AS order_id, n % 12 + 1 AS product_id, n % 7 + 1 AS qty
FROM generate_series(1, 20000) AS n;

ANALYZE big_items;

-- Without an index PostgreSQL reads the whole table (Seq Scan)
EXPLAIN (COSTS OFF) SELECT * FROM big_items WHERE order_id = 42;

-- An index on the column of the WHERE
CREATE INDEX big_items_order_idx ON big_items (order_id);

-- Now it can jump straight to the rows
EXPLAIN (COSTS OFF) SELECT * FROM big_items WHERE order_id = 42;

-- A composite index helps WHERE and ORDER BY at the same time
CREATE INDEX big_items_prod_qty_idx ON big_items (product_id, qty DESC);

EXPLAIN (COSTS OFF)
SELECT id, qty FROM big_items WHERE product_id = 3 ORDER BY qty DESC LIMIT 5;

-- BEGIN opens a transaction: nothing is final until COMMIT
BEGIN;

UPDATE products SET stock = stock - 2 WHERE id = 9;
INSERT INTO orders (customer_id, ordered, status, total)
VALUES (8, '2024-06-10', 'paid', 15.50);

-- A savepoint is a point you can go back to
SAVEPOINT before_discount;
UPDATE orders SET total = 0 WHERE id = 11;
SELECT id, total FROM orders WHERE id = 11;

-- Undo only what came after the savepoint
ROLLBACK TO SAVEPOINT before_discount;
COMMIT;

-- ROLLBACK throws away the whole transaction
BEGIN;
DELETE FROM reviews;
SELECT count(*) AS reviews_inside FROM reviews;
ROLLBACK;

SELECT (SELECT stock FROM products WHERE id = 9) AS cheese_stock,
       (SELECT total FROM orders WHERE id = 11) AS order_11,
       (SELECT count(*) FROM reviews) AS reviews;

-- ON CONFLICT DO NOTHING: the category already exists, nothing happens
INSERT INTO categories (name) VALUES ('Dairy'), ('Frozen')
ON CONFLICT (name) DO NOTHING
RETURNING id, name;

-- A shopping cart: one row per customer and product
CREATE TABLE cart (
  customer_id int REFERENCES customers (id),
  product_id int REFERENCES products (id),
  qty int NOT NULL,
  PRIMARY KEY (customer_id, product_id)
);

INSERT INTO cart VALUES (1, 2, 2), (1, 5, 1);

-- ON CONFLICT DO UPDATE: add to the quantity if the row is there;
-- EXCLUDED is the row that could not be inserted
INSERT INTO cart (customer_id, product_id, qty)
VALUES (1, 2, 3), (1, 9, 1), (2, 2, 1)
ON CONFLICT (customer_id, product_id)
DO UPDATE SET qty = cart.qty + EXCLUDED.qty
RETURNING customer_id, product_id, qty, xmax = 0 AS inserted;

-- A SQL function: one expression, marked IMMUTABLE (same input, same output)
CREATE FUNCTION with_vat(amount numeric, rate numeric DEFAULT 21)
RETURNS numeric LANGUAGE sql IMMUTABLE
AS $$ SELECT round(amount * (1 + rate / 100), 2) $$;

-- A PL/pgSQL function: variables, SELECT INTO and IF
CREATE FUNCTION customer_level(cid int) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  spent numeric;
BEGIN
  SELECT coalesce(sum(total), 0) INTO spent
  FROM orders WHERE customer_id = cid AND status <> 'cancelled';
  IF spent >= 30 THEN
    RETURN 'gold';
  ELSIF spent >= 15 THEN
    RETURN 'silver';
  END IF;
  RETURN 'bronze';
END;
$$;

SELECT with_vat(10) AS vat_21, with_vat(10, 10) AS vat_10;

SELECT name, city, customer_level(id) AS level
FROM customers
ORDER BY id;

-- Where the changes of price will be written down
CREATE TABLE price_changes (
  product_id int, old_price numeric, new_price numeric, changed date
);

-- A trigger function returns trigger and sees OLD and NEW
CREATE FUNCTION log_price() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.price < 0 THEN
    NEW.price := 0;  -- a BEFORE trigger can fix the row
  END IF;
  IF NEW.price <> OLD.price THEN
    INSERT INTO price_changes
    VALUES (OLD.id, OLD.price, NEW.price, date '2024-07-01');
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER products_price
BEFORE UPDATE OF price ON products
FOR EACH ROW EXECUTE FUNCTION log_price();

UPDATE products SET price = price + 0.10 WHERE category_id = 1;
UPDATE products SET price = -1 WHERE id = 11;
UPDATE products SET stock = 99 WHERE id = 7;

SELECT p.name, c.old_price, c.new_price, c.changed
FROM price_changes c JOIN products p ON p.id = c.product_id
ORDER BY c.product_id;

-- One more rule for the products: the price must be positive
ALTER TABLE products ADD CONSTRAINT price_positive CHECK (price > 0);

-- try() runs a statement and returns the error instead of stopping
CREATE FUNCTION try(stmt text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE c text; col text;
BEGIN
  EXECUTE stmt;
  RETURN 'ok';
EXCEPTION WHEN others THEN
  GET STACKED DIAGNOSTICS c = CONSTRAINT_NAME, col = COLUMN_NAME;
  RETURN SQLSTATE || ' ' || coalesce(nullif(c, ''), 'column ' || col);
END;
$$;

SELECT t.what, try(t.stmt) AS result
FROM (VALUES
  ('good row',    'INSERT INTO products (name, price) VALUES (''Honey'', 5)'),
  ('price -1',    'INSERT INTO products (name, price) VALUES (''X'', -1)'),
  ('no name',     'INSERT INTO products (price) VALUES (2)'),
  ('same email',  'UPDATE customers SET email = ''ana@example.com'' WHERE id = 2'),
  ('category 99', 'UPDATE products SET category_id = 99 WHERE id = 1'),
  ('in use',      'DELETE FROM categories WHERE id = 1')
) AS t (what, stmt);

-- Without try(), the error stops the script
INSERT INTO orders (customer_id, ordered) VALUES (99, '2024-07-01');

-- An enum: a type with a fixed list of values, in this order
CREATE TYPE order_status AS ENUM ('new', 'paid', 'shipped', 'cancelled');

ALTER TABLE orders
  ALTER COLUMN status DROP DEFAULT,
  ALTER COLUMN status TYPE order_status USING status::order_status,
  ALTER COLUMN status SET DEFAULT 'new';

SELECT enum_range(NULL::order_status)::text[] AS statuses;

-- A domain: a type with a rule, reusable in any table
CREATE DOMAIN email_address AS text
  CHECK (VALUE ~ '^[^@\s]+@[^@\s]+\.[a-z]+$');

ALTER TABLE customers ALTER COLUMN email TYPE email_address;

SELECT 'ana@example.com'::email_address AS valid;

-- An enum sorts by its list, not alphabetically, and compares with < >
-- ::text shows the label; ORDER BY o.status keeps the enum order
SELECT o.status::text AS status, count(*) AS orders, sum(o.total) AS total,
       o.status < 'shipped' AS pending
FROM orders o
GROUP BY o.status
ORDER BY o.status;
